#include <stdio.h>
#include <assert.h>

// Function to compute factorial
unsigned long long factorial(int n) {
    if (n < 0) {
        return 0; // Error case, though undefined behavior for negative in typical factorial
    }
    unsigned long long result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

// Test function
void test_factorial() {
    printf("Running tests...\n");

    // Test 0! = 1
    assert(factorial(0) == 1);
    printf("Test 1 passed: factorial(0) = %llu\n", factorial(0));

    // Test 1! = 1
    assert(factorial(1) == 1);
    printf("Test 2 passed: factorial(1) = %llu\n", factorial(1));

    // Test 2! = 2
    assert(factorial(2) == 2);
    printf("Test 3 passed: factorial(2) = %llu\n", factorial(2));

    // Test 3! = 6
    assert(factorial(3) == 6);
    printf("Test 4 passed: factorial(3) = %llu\n", factorial(3));

    // Test 4! = 24
    assert(factorial(4) == 24);
    printf("Test 5 passed: factorial(4) = %llu\n", factorial(4));

    // Test 5! = 120
    assert(factorial(5) == 120);
    printf("Test 6 passed: factorial(5) = %llu\n", factorial(5));

    // Test 6! = 720
    assert(factorial(6) == 720);
    printf("Test 7 passed: factorial(6) = %llu\n", factorial(6));

    // Test 10! = 3628800
    assert(factorial(10) == 3628800);
    printf("Test 8 passed: factorial(10) = %llu\n", factorial(10));

    // Test 12! = 479001600
    assert(factorial(12) == 479001600);
    printf("Test 9 passed: factorial(12) = %llu\n", factorial(12));

    printf("All tests passed!\n");
}

int main() {
    test_factorial();

    // Interactive mode
    int n;
    printf("\nEnter a non-negative integer to compute its factorial: ");
    if (scanf("%d", &n) == 1 && n >= 0) {
        printf("factorial(%d) = %llu\n", n, factorial(n));
    } else {
        printf("Invalid input. Please enter a non-negative integer.\n");
    }

    return 0;
}
